const concepts={
fleet:{name:'Supermicro Server Manager',what:'A software console for monitoring and operating supported servers across a fleet.',design:'SSM can reach BMCs through IPMI / Redfish for hardware operations. Licensing and platform support apply; SSM is not the application hypervisor.',src:'ssm'},
bmc:{name:'Embedded BMC',what:'A small management controller that provides hardware status, power control and remote access outside the workload OS.',design:'The Hyper server has its own BMC. Its management path is separate from the application network shown here.',src:'bmc'},
network:{name:'External workload network',what:'The network that connects servers, clients and storage services.',design:'Racks use their own network adapters. A SuperBlade enclosure can aggregate blade links through supported switches or expose them through pass-through modules.',src:'bladechassis'},
nic:{name:'AIOM / network adapter',what:'An adapter supplies Ethernet or other qualified workload connectivity. AIOM is Supermicro’s Advanced I/O Module format based on OCP NIC specifications.',design:'AS-2126HS-TN has an AIOM position plus PCIe expansion. The supported adapter determines ports and speeds; BMC management is a separate role.',src:'aiom'},
cpu:{name:'Two AMD EPYC host processors',what:'CPUs execute the operating system, VMs and general-purpose application code.',design:'AS-2126HS-TN supports two qualified EPYC 9004 / 9005 processors. Each has local memory; the inter-CPU connection lets software use the complete host.',src:'amd2'},
ram:{name:'Host DDR5 memory',what:'DIMMs hold the CPU’s active working data. They are volatile memory, not persistent drives.',design:'This Hyper has 24 slots across its two processors. Populate the supported channels and DIMM types; a slot count is not a memory-channel count.',src:'amd2'},
drives:{name:'Drive bays and backplane',what:'Carriers hold drives; the backplane, cables and controllers determine their electrical path.',design:'AS-2126HS-TN starts with eight SFF bays and offers layouts up to 24. NVMe and SATA layouts need the matching components; M.2 boot storage is separate.',src:'amd2'},
pcie:{name:'PCIe expansion',what:'PCIe connects qualified accelerators, network cards and other I/O devices to the host.',design:'The 2U Hyper can hold up to three double-width GPUs in supported builds. Its page lists both NVIDIA cards and AMD MI210; a spare slot alone is insufficient.',src:'amd2'},
bladechassis:{name:'6U SuperBlade enclosure',what:'An enclosure packages independent server blades with shared infrastructure.',design:'SBE-610J / J2 supports up to ten single-width or five double-width blades in qualified populations. This tour shows ten single-width positions.',src:'bladechassis'},
blade:{name:'Independent compute blade',what:'Each blade is a server with its own CPUs, memory, local storage, management controller and OS.',design:'SBI-622B-1NE34 provides two Xeon 6 sockets, DDR5 and E3.S storage. Ten blades are ten servers, not one twenty-socket shared-memory computer.',src:'blade'},
bladefabric:{name:'Shared network modules',what:'Enclosure switches aggregate traffic; pass-through modules expose blade links without the same switching function.',design:'The 6U X14 enclosure supports qualified 25GbE switch / pass-through configurations. Blade network interfaces reach these modules through the enclosure infrastructure.',src:'bladechassis'},
cmm:{name:'Chassis Management Module',what:'A CMM manages shared blade-enclosure resources and provides chassis-level visibility.',design:'Single or redundant CMM configurations are available. The CMM complements each blade’s BMC; it does not run that blade’s applications.',src:'bladechassis'},
bladepower:{name:'Shared power and cooling',what:'Power supplies and enclosure cooling serve multiple installed compute blades.',design:'Choose a supported power, cooling and blade population together. Liquid-cooling options and switch choices are configuration-specific.',src:'bladechassis'},
host:{name:'The AI host system',what:'Host CPUs and DDR5 run the OS, coordinate work and prepare data for the accelerators.',design:'AS-8126GS-TNMR uses two EPYC 9004 / 9005 CPUs with 24 DIMM slots. Host DDR5 is distinct from each Instinct GPU’s HBM.',src:'instinctair'},
gpu:{name:'AMD Instinct OAM accelerator',what:'A compute module built for highly parallel AI and HPC work, with its own high-bandwidth memory.',design:'This air-cooled platform has eight MI350X or eight MI325X modules in qualified builds. The drawing uses MI350X as its example; modules are not ordinary PCIe add-in cards.',src:'instinctair'},
infinity:{name:'Infinity Fabric GPU connections',what:'High-bandwidth links allow accelerators to exchange data within the GPU subsystem.',design:'The eight Instinct GPUs form an integrated accelerator platform. Lines are grouped to explain roles; they do not represent the physical lane-by-lane topology.',src:'instinctdesign'},
aiio:{name:'PCIe host and cluster I/O',what:'PCIe paths connect host processors, accelerators and qualified I/O adapters. Network adapters then connect separate servers.',design:'AS-8126GS-TNMR offers PCIe 5.0 expansion for scale-out networking. These external links are different from the internal GPU-to-GPU fabric.',src:'instinctair'},
aistorage:{name:'Local AI storage',what:'Persistent drives hold the OS, software, datasets and checkpoints.',design:'The selected air-cooled Instinct system lists eight SFF NVMe bays, two SATA positions and two M.2. More SSD capacity does not enlarge GPU HBM.',src:'instinctair'},
cooling:{name:'Power and air cooling',what:'Power conversion and airflow support the complete server’s electrical and thermal load.',design:'AS-8126GS-TNMR is the 8U air-cooled design. AS-4126GS-NMR-LCC is a separate 4U liquid-cooled model with its own accelerator and facility requirements.',src:'instinctdesign'}
};

const glossary={
'A+ / AS':'Supermicro’s AMD-based server branding and system prefix. The full model identifies a particular chassis and platform.',
'AIOM':'Advanced I/O Module: Supermicro network-adapter format based on OCP NIC specifications. Adapter and system qualification still matter.',
'BMC':'Baseboard Management Controller: hardware management independent of the application operating system.',
'CMM':'Chassis Management Module: manages shared SuperBlade enclosure resources and complements blade-local management.',
'CloudDC':'A family emphasizing cloud data-center deployment. Individual models differ in socket count, storage and modularity.',
'CXL':'Compute Express Link: technology for coherent device / memory connections. A PCIe slot alone does not prove support for a particular CXL device.',
'DC-MHS / DC-SCM':'Modular server hardware standards. DC-SCM separates security and management functions into a module; SYS-112C-TN is an example.',
'DDR5 / DIMM':'DDR5 is a memory technology. A DIMM is the physical memory module; a DIMM slot is not the same thing as a memory channel.',
'E1.S / E3.S':'Different EDSFF storage-device shapes. Both can carry NVMe SSDs, but their carriers and bays are not interchangeable.',
'ECC UDIMM / RDIMM / MRDIMM':'Different memory module designs. ECC detects or corrects memory errors; unbuffered, registered and multiplexed modules have different platform requirements.',
'EPYC 4004 / 4005 / 8004 / 8005 / 9004 / 9005 / 9006':'Different AMD server processor families. CPU socket, motherboard revision, BIOS and thermal qualification determine compatibility.',
'Gaudi 3':'Intel AI accelerator with its own software and Ethernet-based communication design; separate from the Xeon host CPUs.',
'GrandTwin / BigTwin / FlexTwin':'Related multi-node families. GrandTwin focuses on single-socket nodes; BigTwin on dual-socket nodes; FlexTwin on high-density HPC designs. Model details vary.',
'HBM':'High-bandwidth memory attached to an accelerator. It is separate from the host’s DDR5 memory and from SSD storage.',
'HGX / SXM':'HGX is NVIDIA’s integrated GPU platform. SXM is the GPU module format used by selected HGX systems; it is not an ordinary PCIe card.',
'Hyper':'Flexible rack-server family with several CPU, storage and expansion configurations.',
'Infinity Fabric':'AMD interconnect technology. Here it describes communication within the qualified Instinct GPU platform.',
'IPMI / Redfish':'Interfaces used for server hardware management. Supported features and licensing vary with the platform.',
'JBOD / JBOF':'External drive or flash enclosures. An expansion enclosure is not automatically a standalone server with host CPUs and an OS.',
'LFF / SFF':'Large / small form factor: commonly 3.5-inch and 2.5-inch drive bays. Physical size does not establish the storage protocol.',
'M.2':'A compact module shape often used for boot storage. Device and platform determine SATA or NVMe support and serviceability.',
'Node / socket':'A node is an independent computer. A socket is a CPU position within one computer. Four one-socket nodes do not equal one four-socket server.',
'NUMA':'Non-uniform memory access: a processor can access its local memory differently from memory attached to another processor.',
'NVLink / NVSwitch':'NVIDIA GPU interconnect and switching technologies within supported GPU platforms. They differ from external cluster networking.',
'NVMe / SAS / SATA':'Storage protocols or interfaces. A bay, backplane, cables and controllers must support the selected device.',
'OAM':'Open Accelerator Module: a module format used by selected AMD Instinct and Intel Gaudi platforms. The shared format name does not make modules interchangeable.',
'PCIe':'The host expansion interconnect for GPUs, network adapters, storage controllers and other devices.',
'Petascale':'Supermicro’s dense all-flash storage-server family; verify each model’s drive format and CPU configuration.',
'P-core / E-core':'Different Intel Xeon 6 core designs for different workload priorities. A system supporting one does not automatically support every Xeon 6 variant.',
'RAID / HBA':'RAID organizes drives into arrays. A host bus adapter connects storage devices; software-defined storage may prefer direct device access.',
'RoCE':'RDMA over Converged Ethernet: low-overhead data transfer over a configured Ethernet network.',
'SSM / SuperCloud Composer':'Supermicro fleet-management and resource-orchestration tools. They serve different roles from the OS and hypervisor.',
'SuperBlade':'Modular servers installed in an enclosure with shared power, cooling, chassis management and qualified network modules.',
'U / rack unit':'One rack unit is 1.75 inches of vertical rack space. Rack depth, weight and cooling still need separate checks.',
'X14 / H14 / H15':'Supermicro platform-generation labels. They do not directly state Intel or AMD CPU generation numbers.'
};

const quiz=[
{q:'A GrandTwin chassis contains four single-socket nodes. What do you have?',options:['One four-socket shared-memory server','Four independent servers sharing enclosure resources','Four GPUs attached to one host'],answer:1,why:'Each node has its own CPU, memory and operating system. Shared chassis power does not merge them into one computer.',src:'amdtwin'},
{q:'Which pairing is explicitly documented for AS-2126HS-TN?',options:['AMD EPYC with qualified NVIDIA PCIe GPUs or AMD MI210','AMD EPYC means only AMD GPUs','Any GPU that fits a PCIe slot'],answer:0,why:'CPU brand does not choose GPU brand. The exact Hyper model lists NVIDIA options and AMD Instinct MI210, subject to configuration rules.',src:'amd2'},
{q:'What is the most useful distinction between SFF and NVMe?',options:['Both specify drive capacity','SFF is a bay size; NVMe is a storage protocol','NVMe means every 2.5-inch bay accepts the drive'],answer:1,why:'A physical format and a storage protocol describe different properties. Backplanes, controllers and cables determine the supported path.',src:'amdcloud'},
{q:'How does SuperBlade differ from a self-contained rack server?',options:['All blades share one OS and one memory pool','Blades need no CPUs','Independent blades can share power, cooling and enclosure networking'],answer:2,why:'The chassis provides common infrastructure. Each compute blade still has local CPUs, memory and an operating system.',src:'bladechassis'},
{q:'Why check the board revision on AS-2015CS-TNR?',options:['EPYC 9005 support requires motherboard revision 2.x','The revision changes 2U into 4U','Every revision supports every future EPYC processor'],answer:0,why:'A model family can gain CPU support with a newer motherboard revision. The current product name alone is not the full compatibility story.',src:'amdcloud'},
{q:'Does adding SSD capacity increase an Instinct GPU’s HBM?',options:['Yes, all server memory is interchangeable','Only when the SSD uses NVMe','No; persistent storage, host DDR5 and GPU HBM have different roles'],answer:2,why:'An SSD stores datasets and checkpoints. DDR5 supports the host CPU. HBM is local accelerator working memory.',src:'instinctair'},
{q:'What is Intel Gaudi 3 in SYS-822GA-NGR3?',options:['The server’s Xeon CPU socket','An AI accelerator separate from the Xeon host CPUs','A universal replacement for any NVIDIA SXM module'],answer:1,why:'This system combines two Xeon 6900P host CPUs with eight Gaudi 3 OAM accelerators and its own supported software / networking design.',src:'gaudi'},
{q:'What should you infer from separate “up to” drive, GPU and memory values?',options:['All maxima are guaranteed in one build','The largest number always means the fastest server','Each ceiling needs a qualified configuration; some choices compete'],answer:2,why:'Drive cages, risers, GPU clearances, CPU choices, power and thermal limits constrain the complete build. Use the exact model’s configuration rules.',src:'intelhyper'}
];
